#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
using namespace std;

vector<vector<int>> parseVectorVectorInt(const string& s) {
    vector<vector<int>> res;
    size_t i = 0;
    while (i < s.size()) {
        if (s[i] == '[') {
            size_t end = s.find(']', i);
            if (end != string::npos) {
                string sub = s.substr(i + 1, end - i - 1);
                if (!sub.empty() && sub.find('[') == string::npos) {
                    vector<int> row;
                    stringstream ss(sub);
                    string item;
                    while (getline(ss, item, ',')) {
                        if (!item.empty()) row.push_back(stoi(item));
                    }
                    res.push_back(row);
                }
            }
        }
        i++;
    }
    return res;
}

